package com.refind.service.impl;
import com.refind.dao.ClaimDAO; import com.refind.exception.ValidationException; import com.refind.model.Claim; import com.refind.model.enums.ClaimStatus; import com.refind.service.ClaimService; import java.util.*;
public class JdbcClaimService implements ClaimService { private final ClaimDAO dao; public JdbcClaimService(ClaimDAO dao){this.dao=dao;} public Claim submitClaim(Claim c){if(c==null||c.getClaimant()==null||c.getClaimant().getId()==null)throw new ValidationException("Claimant is required.");if(c.getItem()==null||c.getItem().getId()==null)throw new ValidationException("Item is required.");if(c.getStatus()==null)c.setStatus(ClaimStatus.PENDING);return dao.save(c);} public Optional<Claim> getClaimById(Long id){return dao.findById(id);} public List<Claim> getAllClaims(){return dao.findAll();} public List<Claim> getClaimsByClaimant(Long id){return dao.findByClaimant(id);} public List<Claim> getClaimsByItem(Long id){return dao.findByItem(id);} public List<Claim> getClaimsByStatus(ClaimStatus s){return dao.findByStatus(s);} public Claim updateClaim(Claim c){if(c.getId()==null)throw new ValidationException("Claim id is required for update.");return dao.update(c);} public boolean deleteClaim(Long id){return dao.deleteById(id);} }
